referenceSolutions.javascript:
export function solve(events, wait, horizon) {
  let due = null,
    value = null;
  const out = [];
  const advance = (t) => {
    if (due !== null && due <= t) {
      out.push({ time: due, value });
      due = null;
    }
  };
  for (const e of events) {
    advance(e.time);
    if (e.kind === "call") {
      value = e.value;
      due = e.time + wait;
    } else if (e.kind === "cancel") due = null;
    else if (e.kind === "flush" && due !== null) {
      out.push({ time: e.time, value });
      due = null;
    }
  }
  advance(horizon);
  return out;
}

