export function solve(
  events: { time: number; kind: string; value?: any }[],
  wait: number,
  horizon: number,
): any {
  let due: number | null = null,
    value: any = null;
  const out: any[] = [];
  const advance = (t: number): void => {
    if (due !== null && due <= t) {
      out.push({ time: due, value });
      due = null;
    }
  };
  for (const e of events) {
    advance(e.time);
    if (e.kind === "call") {
      value = e.value;
      due = e.time + wait;
    } else if (e.kind === "cancel") due = null;
    else if (e.kind === "flush" && due !== null) {
      out.push({ time: e.time, value });
      due = null;
    }
  }
  advance(horizon);
  return out;
}
